def parenthesis_groups_in_string(paren_string: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    determine if the input is a valid set of parentheses, where each open group is properly closed,
    and not nested in another open group
    >>> parenthesis_groups_in_string('( ) (( )) (( )( ))')
    True
    """
    count = 0
    for character in paren_string:
        if character == '(':
            count += 1
        elif character == ')':
            count -= 1
        if count < 0:
            return False
    if count == 0:
        return True
    return False


