def has_more_close_elements(numbers: List[float], threshold: float) -> bool:
    """ Check if in given list of numbers, is any number closer to other numbers than given
    threshold. Also, the numbers must be more than threshold apart from each other.
    >>> has_more_close_elements([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_more_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True
    """
    for x in range(len(numbers)-1):
        for y in range(x+1,len(numbers)):
            if (abs(numbers[x]-numbers[y])) < threshold and (numbers[x]-numbers[y]) > threshold:
                return True
    return False

    if len(numbers) < 2:
        return False

    low = float("inf")
    high = float("-inf")

    for value in numbers:
        if abs(value - low) < threshold:
            return True
        if abs(value - high) < threshold:
            return True
        low = min(low, value)
        high = max(high, value)

    return False


