    return sum(numbers) / len(numbers)


def variance(numbers: List[float]) -> float:
    """ Calculate the variance of the list of numbers.
    Variance represents how much variation there is from the expected value.
    Variance is the square of the difference between each number in the dataset and the mean.
    >>> variance([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    mean_n = mean(numbers)
    var_sum = 0
    for n in numbers:
        var_sum += (n - mean_n)**2

    return var_sum / len(numbers)


