def deepest_level_of_nested_parens(paren: str) -> int:
    """ Parse string representing multiple groups of nested parentheses and determine the maximum nesting.

    >>> deepest_level_of_nested_parens('(()())')
    2
    """
    depth = 0
    max_depth = 0
    for c in paren:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        max_depth = max(max_depth, depth)
    return max_depth


